<tr><td>Contribution to buyer's agent (assumed, negotiated)</td><td>-$10,000</td><td>-$10,000</td></tr>
<tr><td>Attorney contract review (assumed)</td><td>-$750</td><td>$0</td></tr>
<tr><td>Photos, signs, marketing (assumed)</td><td>-$600</td><td>$0</td></tr>
<tr><td>Possible lower price from pricing or negotiation gaps (assumed)</td><td>-$8,000</td><td>$0</td></tr>
<tr><td><strong>Estimated selling cost</strong></td><td><strong>-$19,850</strong></td><td><strong>-$20,000</strong></td></tr>
</tbody>
